<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Application\Usecase\Render;

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Rendering\Domain\TemplateOutputFormat;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;

/**
 * Input for the template render use case.
 */
class TemplateRenderInput
{
    /**
     * @param array<string, string> $variables Call-site variables that override tenant-level defaults.
     *                                          Keys use dotted notation: "user.name", "login.link".
     */
    public function __construct(
        private readonly string $code,
        private readonly TemplateChannelOptions $channel,
        private readonly ?TenantRef $tenant = null,
        private readonly array $variables = [],
        private readonly TemplateOutputFormat $outputFormat = TemplateOutputFormat::HTML,
    ) {
    }

    /** Template code, e.g. "LOGIN_MAGIC_LINK", "RESET_PASSWORD". */
    public function code(): string
    {
        return $this->code;
    }

    /** Delivery channel used to select among templates with the same code. */
    public function channel(): TemplateChannelOptions
    {
        return $this->channel;
    }

    /** Tenant context. Null means resolve only global templates (no tenant-specific override). */
    public function tenant(): ?TenantRef
    {
        return $this->tenant;
    }

    /** @return array<string, string> */
    public function variables(): array
    {
        return $this->variables;
    }

    /** Desired output format. Defaults to HTML. */
    public function outputFormat(): TemplateOutputFormat
    {
        return $this->outputFormat;
    }
}
